  static void Vec(JToken value){Require(value is JArray&&value.Count()==3&&value.All(n=>(n.Type==JTokenType.Integer||n.Type==JTokenType.Float)&&!double.IsNaN((double)n)&&!double.IsInfinity((double)n)&&Math.Abs((double)n)<=2048),"坐标无效");}
