  static void Phase(JToken anchor,JToken position,JToken rotation){Vec(anchor);double[] a=anchor.ToObject<double[]>(),p=position.ToObject<double[]>();int turn=(((int)rotation%360)+360)%360;double x=a[0],y=a[1];if(turn==90){x=-a[1];y=a[0];}else if(turn==180){x=-a[0];y=-a[1];}else if(turn==270){x=a[1];y=-a[0];}double[] origin={p[0]-x,p[1]-y,p[2]-a[2]};Require(origin.All(v=>Math.Abs(v-Math.Round(v/.25)*.25)<=.000001),"体素几何不对齐0.25米网格");}
