  internal static RuntimeVoxel Voxel(byte[] bytes){var j=Json(bytes);Fields(j,"schema","assetId","revision","name","voxelSize","cells","palette","sideColor","materialProfile","protectedColumns","anchorM","rootMode","provenance","legacyNative");Require((string)j["schema"]=="xinghai-workshop-asset-1"&&AssetId((string)j["assetId"])&&(double?)j["voxelSize"]==.25,"模块契约无效");Revision(j["revision"]);Vec(j["anchorM"]);Require(new[]{"grid","legacy"}.Contains((string)j["rootMode"]),"Root配方无效");if((string)j["rootMode"]=="grid")Require(j["anchorM"].All(n=>(double)n/.25==Math.Round((double)n/.25)),"Root不在0.25米网格");var palette=j["palette"] as JArray;Require(palette!=null&&palette.Count>=1&&palette.Count<=64&&palette.All(p=>Regex.IsMatch((string)p??"","^#[0-9a-fA-F]{6}$")),"色板无效");var cells=j["cells"] as JArray;Require(cells!=null&&cells.Count>0&&cells.Count<=250000,"体素预算无效");var keys=new HashSet<string>();foreach(JObject c in cells){foreach(string axis in new[]{"x","y","z"})Require(c[axis]?.Type==JTokenType.Integer&&Math.Abs((long)c[axis])<=8192,"体素坐标无效");Require(c["color"]?.Type==JTokenType.Integer&&(int)c["color"]>=0&&(int)c["color"]<palette.Count,"体素色板越界");Require(keys.Add(c["x"]+","+c["y"]+","+c["z"]),"重复体素");}
