   return j.ToObject<RuntimeVoxel>();
  }
  public static PublishPackage Read(string manifestPath){string root=Path.GetDirectoryName(Path.GetFullPath(manifestPath));byte[] raw=File.ReadAllBytes(Safe(root,Path.GetFileName(manifestPath)));var j=Json(raw);Fields(j,"schema","publishId","kind","targetId","sourceRevision","unit","sourceAxes","voxelSize","recipe","runtimePath","dependencies","outputFiles","payloadFiles","toolchain");foreach(JObject row in j["payloadFiles"].Concat(j["outputFiles"])){Fields(row,"path","sha256","byteLength");Require(row["byteLength"]?.Type==JTokenType.Integer,"文件长度必须是整数");}foreach(JObject dependency in j["dependencies"]){Fields(dependency,"assetId","kind","sourceRevision","contentHash","sourcePath","anchorM","glbPath","unity");Revision(dependency["sourceRevision"]);}var m=j.ToObject<PublishManifest>();Require(m.schema=="xinghai-workshop-publish-1"&&Id(m.publishId)&&(m.kind=="asset"?AssetId(m.targetId):Id(m.targetId))&&new[]{"asset","scene"}.Contains(m.kind),"发布包schema/身份无效");Revision(j["sourceRevision"]);Require(m.unit=="meters"&&m.sourceAxes=="RH_Z_UP"&&m.voxelSize==.25f&&new[]{"glb-only","glb-fbx"}.Contains(m.recipe),"轴或发布配方无效");Require(m.toolchain!=null&&!string.IsNullOrEmpty(m.toolchain.workshopVersion)&&Regex.IsMatch(m.toolchain.sourceFingerprint??"","^[0-9a-f]{64}$"),"工具链指纹无效");Require(m.dependencies!=null&&m.dependencies.Length>0&&m.dependencies.Length<=10000&&m.payloadFiles!=null&&m.outputFiles!=null,"发布闭包无效");
   var files=new Dictionary<string,byte[]>(StringComparer.Ordinal);var folded=new HashSet<string>(StringComparer.OrdinalIgnoreCase);long budget=0;foreach(var f in m.payloadFiles.Concat(m.outputFiles)){Require(f!=null&&folded.Add(f.path??""),"重复闭包路径");Require(f.byteLength>=0&&f.byteLength<=64*1024*1024&&Regex.IsMatch(f.sha256??"","^[0-9a-f]{64}$"),"文件长度/hash无效");budget+=f.byteLength;Require(budget<=1024L*1024*1024,"发布闭包预算超限");var bytes=File.ReadAllBytes(Safe(root,f.path));Require(bytes.LongLength==f.byteLength&&Hash(bytes)==f.sha256,"冻结文件hash不匹配："+f.path);files.Add(f.path,bytes);}
