    else if(d.kind=="external"){Require(d.unity.route=="fbx","外部GLB不能直接接收，请重新发布 glb-fbx");Require(m.recipe=="glb-fbx"&&m.toolchain.blenderVersion=="5.1.2"&&m.toolchain.fbxRecipe=="blender-fbx-5.1.2"&&d.unity.recipe=="blender-fbx-5.1.2","未验证FBX轴配方");Vec(JToken.FromObject(d.anchorM));var source=Json(file(d.sourcePath));Require((string)source["assetId"]==d.assetId&&(int?)source["revision"]==d.sourceRevision&&d.anchorM.SequenceEqual(source["anchorM"].ToObject<float[]>()),"外部源绑定不匹配");var fbx=file(d.unity.modelPath);Require(fbx.Length>=27&&Encoding.ASCII.GetString(fbx,0,21)=="Kaydara FBX Binary  \0","FBX无效");var side=Json(file(d.unity.materialsPath));Require((string)side["schema"]=="xinghai-fbx-materials-1"&&side["colors"] is JArray&&side["textureDependencies"] is JArray&&d.unity.texturePaths!=null,"FBX材质旁车无效");var expected=new HashSet<string>();foreach(var tex in side["textureDependencies"]){string relative=(string)tex;PathCheck(relative);string full=(Path.GetDirectoryName(d.unity.materialsPath).Replace('\\','/')+"/"+relative);expected.Add(full);Png(file(full));}Require(expected.SetEquals(d.unity.texturePaths),"FBX贴图闭包不匹配");foreach(var c in side["colors"]){string texture=(string)c["baseColorTexturePath"];if(texture!=null)Require(expected.Contains(Path.GetDirectoryName(d.unity.materialsPath).Replace('\\','/')+"/"+texture),"材质贴图缺失");}}
